#define PI 3.14159265
#define resolution iResolution
#define mouse iMouse

vec3 rand3(vec3 p){
    return fract(4249.689779*vec3(
                sin(dot(p, vec3(5.9333, 6.2459, 5.9539))), 
                sin(dot(p, vec3(6.2201, 6.1757, 6.2233))),
                sin(dot(p, vec3(6.4849, 5.8889, 6.3029 )))
                ));
}

vec4 voronoi3(vec3 p){
    vec3 uf = floor(p);
    vec3 uv = fract(p);
    float c = 1.;
    vec3 o = p;
    for(int i = -1;i <= 1;i ++)
        for(int j = -1; j <= 1 ; j++){
            int k = -1;
            float du;

            vec3 d = vec3(i, j, -1);
            vec3 u = d - uv + rand3(uf + d);
            du = dot(u,u);
            if(c > du){
                c = du;
                o = uf + d;
            }

            d.z = 0.;
            u = d - uv + rand3(uf + d);
            du = dot(u,u);
            if(c > du){
                c = du;
                o = uf + d;
            }

            d.z = 1.;
            u = d - uv + rand3(uf + d);
            du = dot(u,u);
            if(c > du){
                c = du;
                o = uf + d;
            }
        }
    return vec4(o, c);
}

#define MAX 10.
float iSphere(vec3 ro, vec3 rd, vec4 sp){
    float t = dot(rd, sp.xyz - ro);
    vec3 rs = ro + rd * t - sp.xyz;
    float k = sp.w*sp.w - dot(rs,rs);
    float h = MAX;
    if( k < 0.){
        h = -1.;
    } else {
        h = sqrt(k);
        float n = t - h;
        float f = t + h;
        if(f < 0.)h = -1.;
        else if (n < 0.) h = f;
        else if (n < f ) h = n;
    }
    return h;
}

vec3 nSphere(vec3 rp, vec4 sp){
    return (rp - sp.xyz)/sp.w;
}

struct Cube {
    vec3 pos;
    vec3 size;
    vec3 normal;
};

Cube cu;

#define max3(a) max((a).x,max((a).y,(a).z))
#define min3(a) min((a).x,min((a).y,(a).z))
float iCube(vec3 ro, vec3 rd,inout Cube c){
    float intr = -1.;
    vec3 rel_ro = ro - c.pos;
    vec3 k = c.size/abs(rd);
    vec3 n = rel_ro/rd;
    vec3 t1 = -n - k;
    vec3 t2 = -n + k;
    float tNear = max3(t1);
    float tFar = min3(t2);
    if(tNear > tFar || tFar < 0.)intr = -1.;
    else if(tNear < 0.){
        intr = tFar;
        c.normal = step(t2,vec3(tFar));
    } else {
        intr = tNear;
        c.normal = step(vec3(tNear),t1);
    }
    c.normal *= -sign(rd);
    return intr;
}

vec3 nCube(Cube c){
    return c.normal;
}


vec2 intersect(vec3 ro, vec3 rd){
    int mat = -1;
//    float d = iSphere(ro, rd, vec4(0,0,0,1));
    float d = iCube(ro, rd, cu);
    if(d > 0.) mat = 0;
    return vec2(d, mat);
}

mat3 matLookAt(vec3 lookAt, vec3 up){
    lookAt = normalize(lookAt);
    up = normalize(up);
    vec3 right = normalize(cross(lookAt, up));
    vec3 top = normalize(cross(right, lookAt));
    return mat3(right, top, -lookAt);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord){
    fragColor = vec4(0,0,0,1);
    vec2 uv = (2.*fragCoord.xy - resolution.xy)/resolution.y;
    vec2 m = (2.*mouse.xy - resolution.xy)/resolution.y;
    if(iMouse.z <= 0.){
        m.x = sin(iTime*0.20)*1.5;
        m.y = cos(iTime*0.20)*0.5;
    }

    // value imported from my editor https://gitea.com/Silica163/fragment-loader
    vec4 uVec40 = vec4(0,.5,1., 0); // inside color
    vec4 uVec41 = vec4(1,.4,0, 0);  // outside color
    vec4 uVec42 = vec4(0,0,0,2.2);  // rgb => background color, a => camera distance
    vec4 uVec43 = vec4(6,3,1.,.9);  // rg => inside-outside scaler, b => transparent, a => transition speed between inside and outside

    vec3 ro = normalize(vec3(sin(m.x*PI),m.y,cos(m.x*PI)))*uVec42.w;
    vec3 rd = matLookAt(-ro, vec3(0,1,0))*vec3(uv, -1);

    cu.size = vec3(1);
    cu.pos = vec3(0);

    vec2 i = intersect(ro, rd);

    vec3 rp = ro + rd * i.x;
    vec3 c = uVec42.xyz;
    if(i.y == 0.){
        rp += rd * 1e-4;
        float d = intersect(rp, rd).x;
        const int steps = 10;
        float invS = d/float(steps);
        vec3 rs = invS * rd;
        vec4 acc = vec4(0);

        for(int i = 0; i < steps; i ++){
            float l = length(rp)*uVec43.w;
            float v = voronoi3(rp * mix(uVec43.x,uVec43.y,l)).w; 
            vec4 cnow = mix(uVec40, uVec41, l);
            acc.rgb = mix(acc.rgb, cnow.rgb, v);
            acc.a +=  v * invS * uVec43.z;
            rp += rs;
        }

        acc = clamp(acc, 0., 1.);
        c = mix(c, acc.rgb, acc.a);
    }

    fragColor.rgb = sqrt(c);
}
